"""Data classes for Mosaiq staff"""

from dataclasses import dataclass
from enum import Enum

class CodeCapture(Enum):
    code_capture_single = 0
    code_capture_multi = 1
    code_capture_use_department_config = 2
    unknown = 3

class ResolutionBasedUISetting(Enum):
    resolution_based_ui_setting_no = 0
    resolution_based_ui_setting_yes = 1
    resolution_based_ui_setting_use_departmennt_config = 2
    unknown = 3

@dataclass
class Staff:
    '''
    Data class of Staff
    '''
    last_name: str = ""
    first_name: str = ""
    mdl_initials: str = ""
    initials: str  = ""
    suffix: str = ""
    alt_last_name: str = ""
    alt_first_name: str = ""
    alt_mdl_initial: str = ""

    user_name: str = ""
    clinical_id: str = ""
    department: str = ""
    type: str = ""
    active: bool = False
    category: str = ""
    accepts_assignment: bool = False
    code: str = ""
    non_physician: bool = False
    page: str = ""
    ext_1: str = ""
    work: str = ""
    ext_2: str = ""
    fax: str = ""
    email: str = ""
    direct_email: str = ""

    #schedule
    duration: str = ""
    schedulable: bool = False
    code_capture: CodeCapture = CodeCapture.unknown

    #creditials
    billing: str = ""
    other: str = ""

    #user resolution based UI settings
    resolution_based_ui_setting: ResolutionBasedUISetting= ResolutionBasedUISetting.unknown

    #identification
    upin: str = ""
    ssn: str = ""
    license: str = ""
    npi: str = ""

    #personal
    address_1: str = ""
    address_2: str = ""
    city: str = ""
    state: str = ""
    postal: str = ""
    phone: str = ""
    ext: str = ""
    gender: str = ""
    dob: str = ""


